// N+1 vs a hand-written DataLoader, measured by counting "SQL" calls.
const names = { 1: 'Asha', 2: 'Ben', 3: 'Chen' };
const posts = Array.from({ length: 8 }, (_, i) => ({ id: i + 1, authorId: (i % 3) + 1 }));
let sqlCalls = 0;
const sql = {
  userById: async (id) => { sqlCalls++; return { id, name: names[id] }; },
  usersByIds: async (ids) => {                 // rows come back in ANY order
    sqlCalls++;
    return ids.slice().reverse().map(id => ({ id, name: names[id] }));
  }
};

class DataLoader {
  constructor(batchFn) { this.batchFn = batchFn; this.cache = new Map(); this.queue = []; }
  load(key) {
    if (this.cache.has(key)) return this.cache.get(key);      // per-request cache
    const p = new Promise((resolve) => {
      this.queue.push({ key, resolve });
      if (this.queue.length === 1) process.nextTick(() => this.dispatch()); // run after this tick
    });
    this.cache.set(key, p);
    return p;
  }
  async dispatch() {
    const batch = this.queue; this.queue = [];
    const values = await this.batchFn(batch.map(b => b.key));  // ONE call for all keys
    batch.forEach((b, i) => b.resolve(values[i]));
  }
}

async function run(label, authorOf) {
  sqlCalls = 1;                                // the 1 query that loaded the posts
  const out = await Promise.all(posts.map(p => authorOf(p).then(u => u.name)));
  console.log(label.padEnd(11), 'queries =', sqlCalls, '|', out.join(','));
}

(async () => {
  console.log('post author ids:', posts.map(p => p.authorId).join(','));
  await run('naive', (post) => sql.userById(post.authorId));
  const loader = new DataLoader(async (ids) => {
    const rows = await sql.usersByIds(ids);
    const byId = new Map(rows.map(r => [r.id, r]));
    return ids.map(id => byId.get(id) || null);   // same order and length as keys
  });
  await run('dataloader', (post) => loader.load(post.authorId));
})();

