# Protocol Buffers wire format by hand: varints, tags, zigzag.
import json

def varint(n):
    out = bytearray()
    while True:
        low = n & 0x7F                 # 7 bits per byte
        n >>= 7
        if n:
            out.append(low | 0x80)     # high bit = "more bytes follow"
        else:
            out.append(low)
            return bytes(out)

def tag(field_number, wire_type):
    return varint((field_number << 3) | wire_type)

def zigzag(n):                          # sint32: small negatives stay small
    return (n << 1) ^ (n >> 31)

# message User { int32 id = 1; string name = 2; bool active = 3; }
user = {"id": 150, "name": "Asha", "active": True}
msg = bytearray()
msg += tag(1, 0) + varint(user["id"])                    # wire type 0 = varint
name = user["name"].encode()
msg += tag(2, 2) + varint(len(name)) + name              # wire type 2 = length-delimited
msg += tag(3, 0) + varint(1)

print("message:", user)
print("protobuf bytes:", len(msg), msg.hex(" "))
print("json bytes    :", len(json.dumps(user, separators=(",", ":"))))
print("varint(1) =", varint(1).hex(), " varint(300) =", varint(300).hex())
print("zigzag(-1) =", zigzag(-1), "-> 1 byte;  plain int32 -1 would take 10 bytes")

# Deadline propagation: each hop gets the REMAINING budget, not a fresh timeout.
class DeadlineExceeded(Exception):
    pass

class Clock:
    now = 0.0                          # simulated time in seconds

def call(name, work_seconds, deadline, downstream=None):
    # Check the deadline before doing any work.
    if Clock.now >= deadline:
        raise DeadlineExceeded(f"{name}: no budget left at t={Clock.now:.1f}")
    print(f"t={Clock.now:.1f} {name} starts, remaining={deadline - Clock.now:.1f}s")
    Clock.now += work_seconds
    if Clock.now > deadline:                  # the caller has already given up
        raise DeadlineExceeded(f"{name}: finished at t={Clock.now:.1f}, too late")
    if downstream:
        # Pass the SAME absolute deadline on; remaining time shrinks automatically.
        downstream(deadline)
    return "ok"

def payment(deadline): call("payment", 0.6, deadline)
def inventory(deadline): call("inventory", 0.5, deadline, payment)

def request(total_budget):
    Clock.now = 0.0
    deadline = Clock.now + total_budget       # absolute point in time
    try:
        call("api", 0.2, deadline, inventory)
        print("result: success\n")
    except DeadlineExceeded as e:
        print("result: DEADLINE_EXCEEDED ->", e, "\n")

print("--- budget 2.0s ---"); request(2.0)
print("--- budget 1.0s ---"); request(1.0)
# With a fresh 1s timeout per hop, payment would still run at t=0.7 for work nobody waits for.
